/* Talk: conversation AX (speaker, choices, 0); returns the choice. */
static void sins2_Talk(uint16_t ax)
{
    svc_Talk(ax);
    return;
}

/* Say: one line, BX, said by AX (0: narration). */
static void sins2_Say(uint16_t ax, uint16_t bx)
{
    fv_talk_buf = ax;
    CS_W(0xDA) = bx;
    CS_W(0xDC) = 0;
    sins2_Talk(talk_buf);
    return;
}

/* The room starts: the inner door. Until Uhura's call (tick 40) the
 * party can't move.
 * [MSG_TICK 01 00 00] */
static void sins2_StartRoom(void)
{
    svc_Sfx(N_SIN2LOOP);
    svc_Music(0x1B, -3);
    if (rv_virus_found == 0) {
        room.busy = 2;
    }
    if (rv_door_open2 == 1) {
        svc_Anim(8, N_s2dro, 0, 0, 1);
        svc_LoadMap(N_sins22);
        return;
    }
    svc_LoadMap(N_sins2);
    return;
}

